from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.previous_averages_ready = False
        self.pending_entry_signal = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.pending_entry_symbol = None

        self.held_option = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.no_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        prior_fast = self.previous_fast
        prior_slow = self.previous_slow
        prior_ready = self.previous_averages_ready

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        current_ready = self.fast.IsReady and self.slow.IsReady
        if (
            current_ready
            and prior_ready
            and prior_fast <= prior_slow
            and self.fast.Current.Value > self.slow.Current.Value
            and bar.EndTime.time() >= datetime.time(9, 45)
            and bar.EndTime.time() <= datetime.time(14, 30)
        ):
            self.pending_entry_signal = True

        if current_ready:
            self.previous_fast = self.fast.Current.Value
            self.previous_slow = self.slow.Current.Value
            self.previous_averages_ready = True
        else:
            self.previous_averages_ready = False

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProcessing()
        self.HandleOptionExit(data)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.no_entry_date == self.Time.date():
            return

        if (
            self.held_option is not None
            or self.entry_ticket is not None
            or self.exit_ticket is not None
        ):
            return

        if self.spy not in data.Bars:
            self.Debug(f"{self.Time}: skipped entry selection; SPY price unavailable")
            return

        spy_price = data.Bars[self.spy].Close
        if spy_price <= 0:
            self.Debug(f"{self.Time}: skipped entry selection; invalid SPY price")
            return

        contracts = []
        for chain in data.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right == OptionRight.Call:
                    contracts.append(contract)

        if not contracts:
            self.Debug(f"{self.Time}: skipped entry selection; no option chain")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        eligible_expiries = sorted(
            {contract.Expiry.date() for contract in contracts
             if contract.Expiry.date() >= minimum_expiry}
        )

        if not eligible_expiries:
            self.Debug(f"{self.Time}: skipped entry selection; no expiration at least 7 days out")
            return

        expiry = eligible_expiries[0]
        minimum_strike = spy_price * 1.01
        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: skipped entry selection; no qualifying call for {expiry}"
            )
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        self.pending_entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1, tag="Bullish MA crossover entry")
        self.Debug(
            f"{self.Time}: entry submitted {selected.Symbol} "
            f"expiry={expiry} strike={selected.Strike}"
        )

    def HandleOptionExit(self, data):
        if (
            self.held_option is None
            or self.entry_fill_price is None
            or self.exit_ticket is not None
        ):
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.Time.date() < self.held_expiry:
            previous_trading_day = self.Securities[
                self.spy
            ].Exchange.Hours.GetPreviousTradingDay(self.held_expiry).date()

            if (
                self.Time.date() == previous_trading_day
                and self.Time.time() == datetime.time(15, 45)
            ):
                self.SubmitExit("Pre-expiration time stop")
                return

        quote = self.GetCurrentQuote(data, self.held_option)
        if quote is None:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.SubmitExit("50% profit target")

    def GetCurrentQuote(self, data, symbol):
        for chain in data.OptionChains.Values:
            if symbol in chain.Contracts:
                contract = chain.Contracts[symbol]
                if contract.BidPrice > 0 and contract.AskPrice > 0:
                    return contract.BidPrice, contract.AskPrice
        return None

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        self.Transactions.CancelOpenOrders(self.held_option)
        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(f"{self.Time}: exit submitted {self.held_option}; {reason}")

    def HandleExpirationProcessing(self):
        if self.held_option is None or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry:
            self.no_entry_date = self.Time.date()
            if self.exit_ticket is None and self.Portfolio[self.held_option].Quantity > 0:
                self.SubmitExit("Expiration safety liquidation")
                self.Debug(
                    f"{self.Time}: expiration safety liquidation submitted "
                    f"for {self.held_option}"
                )

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if not self.Transactions.GetOpenOrders(self.spy):
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
            self.Debug(
                f"{self.Time}: unexpected SPY exercise/assignment position; "
                f"liquidation submitted"
            )

    def OnOrderEvent(self, orderEvent):
        if self.entry_ticket is not None and orderEvent.OrderId == self.entry_ticket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.held_option = orderEvent.Symbol
                self.held_expiry = orderEvent.Symbol.ID.Date.date()
                self.entry_fill_price = orderEvent.FillPrice
                self.entry_ticket = None
                self.pending_entry_symbol = None
                self.Debug(
                    f"{self.Time}: entry filled {self.held_option} "
                    f"at {self.entry_fill_price}"
                )
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_ticket = None
                self.pending_entry_symbol = None
                self.Debug(f"{self.Time}: entry order did not fill")

        if self.exit_ticket is not None and orderEvent.OrderId == self.exit_ticket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(f"{self.Time}: exit filled {orderEvent.Symbol}")
                self.exit_ticket = None
                self.held_option = None
                self.held_expiry = None
                self.entry_fill_price = None
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_ticket = None

