        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        crossed_up = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not crossed_up:
            return

        if not (
            (bar.EndTime.hour == 9 and bar.EndTime.minute >= 45)
            or 10 <= bar.EndTime.hour <= 13
            or (bar.EndTime.hour == 14 and bar.EndTime.minute <= 30)
        ):
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.held_contract is not None or self.entry_order_id is not None:
            return

        self._try_enter_from_current_slice()

    def _try_enter_from_current_slice(self):
        data = self.CurrentSlice
        if data is None or not data.OptionChains:
            self.Debug("Entry skipped: no option chain in current Slice.")
            return

        spy_price = self.Securities[self.spy.Symbol].Price
        if spy_price <= 0:
            self.Debug("Entry skipped: invalid SPY price.")
            return

        current_date = self.Time.date()
        eligible_expirations = []
        contracts_by_expiry = {}

        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                if (expiry_date - current_date).days < 7:
                    continue

                if expiry_date not in contracts_by_expiry:
                    contracts_by_expiry[expiry_date] = []
                    eligible_expirations.append(expiry_date)

                contracts_by_expiry[expiry_date].append(contract)

        if not eligible_expirations:
            self.Debug("Entry skipped: no call expiration at least 7 calendar days away.")
            return

        selected_expiry = min(eligible_expirations)
        minimum_strike = spy_price * 1.01
        candidates = [
            contract
            for contract in contracts_by_expiry[selected_expiry]
            if contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying OTM call at selected expiration.")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        if ticket is None or ticket.OrderId <= 0:
            self.Debug("Entry skipped: market order could not be submitted.")
            return

        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {selected.Expiry.date()}, "
            f"strike {selected.Strike}."
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                order = self.Transactions.GetOrderById(order_event.OrderId)
                self.held_contract = order.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.exit_order_id = None
                self.time_stop_date = self._previous_spy_trading_day(
                    self.held_contract.ID.Date.date()
                )
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_price:.2f}."
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.entry_order_id = None
                self.Debug(f"Entry order did not fill: {order_event.Status}.")

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self.held_contract} at {order_event.FillPrice:.2f}.")
                self.held_contract = None
                self.entry_price = None
                self.exit_order_id = None
                self.time_stop_date = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.exit_order_id = None

        if (
            order_event.OrderId == self.equity_liquidation_order_id
            and order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            )
        ):
            self.equity_liquidation_order_id = None

    def _submit_exit(self, reason: str):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        for open_order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(open_order.Id)

        ticket = self.MarketOrder(self.held_contract, -quantity)
        if ticket is not None and ticket.OrderId > 0:
            self.exit_order_id = ticket.OrderId
            self.Debug(f"Exit submitted ({reason}): {self.held_contract}.")

    def _contract_from_slice(self, data: Slice, symbol: Symbol):
        if data is None or not data.OptionChains:
            return None

        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _previous_spy_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

