        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity == 0 or self.equity_liquidation_order_id is not None:
            return

        ticket = self.MarketOrder(self.spy.Symbol, -quantity)
        if ticket is not None and ticket.OrderId > 0:
            self.equity_liquidation_order_id = ticket.OrderId
            self.Debug(
                f"Unexpected SPY exercise/assignment position detected; "
                f"liquidation submitted for {quantity} shares."
            )

