                    self.SubmitExit("pre-expiration time stop")

                self.CheckProfitTarget(data)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.Time.date() in self.no_entry_dates:
            return

        if self.held_contract is not None:
            return

        if self.IsTicketOpen(self.entry_ticket) or self.IsTicketOpen(self.exit_ticket):
            return

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug("Entry skipped: no current SPY price.")
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no option chain.")
            return

        minimum_expiration = self.Time.date() + timedelta(days=7)
        expirations = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if contract.Expiry.date() >= minimum_expiration
            }
        )

        if not expirations:
            self.Debug("Entry skipped: no expiration at least seven calendar days out.")
            return

        selected_expiration = expirations[0]
        minimum_strike = spy_bar.Close * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        contract = candidates[0]

        self.entry_ticket = self.MarketOrder(contract.Symbol, 1)
        self.Debug(
            f"Entry submitted: {contract.Symbol}, expiry {selected_expiration}, "
            f"strike {contract.Strike}."
        )

    def CheckProfitTarget(self, data):
        if self.held_contract is None or self.entry_fill_price is None:
            return

        quote = data.QuoteBars.get(self.held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        if self.IsTicketOpen(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
        self.Debug(f"Exit submitted: {reason}, {self.held_contract}.")

    def HandleUnexpectedSpyPosition(self):
        if not self.Portfolio[self.spy].Invested:
            return

        if self.IsTicketOpen(self.spy_liquidation_ticket):
            return

        quantity = self.Portfolio[self.spy].Quantity
        self.spy_liquidation_ticket = self.MarketOrder(self.spy, -quantity)
        self.Debug("Unexpected SPY exercise/assignment position detected; liquidating.")

    def PreviousTradingDay(self, expiration):
        candidate = expiration - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def IsTicketOpen(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted
        ]

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_fill_price}."
                )

            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                if order_event.Status != OrderStatus.Filled or order_event.FillQuantity <= 0:
                    self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice}.")
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_contract = None
                    self.entry_fill_price = None
                    self.exit_ticket = None

            if order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_ticket = None

        if (
            self.spy_liquidation_ticket is not None
            and order_event.OrderId == self.spy_liquidation_ticket.OrderId
            and order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]
        ):
            self.spy_liquidation_ticket = None
